
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_r2scan_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_r2scan", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.884470562916754e+00, -4.785578822927964e+00, -4.646965586471302e+00, -4.454862142173067e+00, -4.192903711585563e+00, -3.843837165039351e+00, -3.393634419454914e+00, -2.838900995774081e+00, -2.196548861460761e+00, -1.502541528027583e+00, -8.498869023926899e-01, -6.159550045937843e-01, -6.300159197287288e-01, -5.313006207164696e-01, -3.623088959487222e-01, -1.977149421216855e-01, -7.883547205203568e-02, -2.115011726779801e-02, -2.966659956869712e-03, -1.387598798852837e-04]))
    err = ns.abs(tgt-ref_tgt)/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    tol = ns.full_like(tgt, ns.asarray([5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-08, 5.000000000000000e-07]))
    assert bool(ns.all(err < tol))


